// Hard defaults you can change
const defaults = {
  bucket: "tools-bucket-cloudranger-30293812",
  prefix: "",  // optional path (no leading '/')
  ignoreFolders: ["processed","backups"],
  mainIndex: "security-findings",
  eventsIndex: "security-findings-events",
  processedPrefix: "processed/",             // where to move inside the same bucket
  processedBucket: "",                       // leave blank to keep same bucket

};

// Webhook sends either {body:{...}} or raw JSON
const raw = ($json.query && typeof $json.body === 'object') ? $json.query : $json;

// normalize ignoreFolders (array or comma-separated string)
let ignore = raw.ignoreFolders;
if (typeof ignore === 'string') {
  ignore = ignore.split(',').map(s => s.trim()).filter(Boolean);
}
if (!Array.isArray(ignore)) ignore = undefined;

// normalize prefix: strip slashes, then make folderKey (trailing slash if non-empty)
const p = (raw.tool ?? defaults.prefix ?? '').toString().replace(/^\/+|\/+$/g,'');
const folderKey = p ? (p.endsWith('/') ? p : p + '/') : '';

// final config
const cfg = {
  ...defaults,
  ...raw,
  ...(ignore ? { ignoreFolders: ignore } : {}),
  prefix: p,          // clean, no slashes
  folderKey           // S3 "Folder Key" friendly
};

return [{ json: cfg }];

const cfg = $items('Apply Defaults')?.[0]?.json || {};
const ignore = (cfg.ignoreFolders || []).map(s => String(s).replace(/\/+$/,''));
const out = [];

for (const it of $items('List Files')) {
  const key = it.json.Key || it.json.key || '';
  if (!key.toLowerCase().endsWith('.json')) continue;

  // skip ignored folders (prefix match)
  if (ignore.some(pre => pre && (key === pre || key.startsWith(pre + '/')))) continue;

  // tag tool by path/name
  let tool = 'unknown';
  if (/zaproxy|zap/i.test(key)) tool = 'zaproxy';
  else if (/checkov/i.test(key)) tool = 'checkov';
  else if (/trufflehog/i.test(key)) tool = 'trufflehog';
  else if (/kubescape/i.test(key)) tool = 'kubescape';
  else if (/trivy/i.test(key)) tool = 'trivy';
  else if (/prowler/i.test(key)) tool = 'prowler';



  out.push({
    json: {
      bucket: cfg.bucket,
      key,
      tool,
      mainIndex: cfg.mainIndex,
      eventsIndex: cfg.eventsIndex
    }
  });
}

return out;

// ================== Parse & Normalize (ZAP, Checkov, TruffleHog, Kubescape, Trivy, Prowler) ==================
// Drop-in for an n8n Code node. Consumes items from "Extract from file" (one per S3 object).
// Emits one normalized {mainDoc,eventDoc} per atomic finding, with s3 taken ONLY from the same input item.
// References are extracted into a top-level `references: []` field.
// NOTE: For Trivy specifically, `references` begins with REMEDIATION GUIDANCE lines, followed by the PrimaryURL.
//       If no guidance can be built, `references` falls back to just the PrimaryURL.
//       Also for Trivy, this parser pulls IMAGE DIGEST (RepoDigest/ImageID) and LAYER DIGEST (per finding).

// ---------- helpers ----------
function fnv1a64Hex(str){
  let h = BigInt('0xcbf29ce484222325'), p = BigInt('0x100000001b3');
  for (let i = 0; i < str.length; i++){ h ^= BigInt(str.charCodeAt(i)); h = (h * p) & BigInt('0xFFFFFFFFFFFFFFFF'); }
  return h.toString(16).padStart(16,'0');
}
const fingerprintOf = (tool, signature) => fnv1a64Hex(JSON.stringify({ tool, signature }));

const ZAP_RISK = { "0":"Informational", "1":"Low", "2":"Medium", "3":"High" };
const ZAP_CONF = { "1":7, "2":4, "3":2, "4":1 }; // higher = more confident

const normParam  = (p) => (p === '' || p == null) ? null : String(p).trim().toLowerCase();
const normMethod = (m) => { const v = (m || '').toString().trim().toUpperCase(); return v || null; };
const normPath   = (p) => p ? String(p).replace(/\\/g,'/').trim() : null;
function normRepoUrl(u){
  if (!u) return null;
  try { const url = new URL(u); url.hash=''; url.search=''; return url.origin + url.pathname.replace(/\.git$/,''); }
  catch { return u; }
}
function sevCheckov(v){
  if (!v) return 'Medium';
  const s = String(v).toLowerCase();
  if (s.startsWith('info')) return 'Informational';
  if (s === 'low') return 'Low';
  if (s === 'medium') return 'Medium';
  if (s === 'high') return 'High';
  if (s === 'critical') return 'Critical';
  return 'Medium';
}
function sevUpperToTitle(s){
  if (!s) return 'Medium';
  const k = String(s).toUpperCase();
  if (k === 'INFO' || k === 'INFORMATIONAL') return 'Informational';
  if (k === 'LOW') return 'Low';
  if (k === 'MEDIUM') return 'Medium';
  if (k === 'HIGH') return 'High';
  if (k === 'CRITICAL') return 'Critical';
  return 'Medium';
}
function nonEmptyLines(arr){
  return (arr || []).map(x => (x ?? '').toString().trim()).filter(Boolean);
}
function flattenCompliance(obj){
  if (!obj || typeof obj !== 'object') return [];
  const out = [];
  for (const [framework, ids] of Object.entries(obj)) {
    if (Array.isArray(ids) && ids.length) out.push(`${framework}: ${ids.join(', ')}`);
  }
  return out;
}
function unique(arr){
  return Array.from(new Set((arr || []).filter(Boolean)));
}
function extractUrls(val){
  const urls = [];
  const push = (s) => {
    if (!s) return;
    const m = String(s).match(/\bhttps?:\/\/[^\s)]+/g);
    if (m) urls.push(...m);
  };
  if (Array.isArray(val)) val.forEach(push); else push(val);
  return unique(urls);
}

// ---------- ZAP parser ----------
function parseZap(scan){
  const sites  = Array.isArray(scan?.site) ? scan.site : [];
  const alerts = sites.flatMap(s => s?.alerts || []);
  const rows = [];

  for (const a of alerts){
    const title    = (a.alert || a.name || 'ZAP Finding').trim();
    const pluginid = String(a.pluginid || '').trim();
    const desc     = a.desc || a.description || '';
    const severity = ZAP_RISK[String(a.riskcode ?? '')] || ((a.riskdesc||'').split(' ')[0] || 'Informational');
    const conf     = ZAP_CONF[String(a.confidence ?? '')] ?? null;
    const cwe      = a.cweid || a.cwe || null;
    const siteOwner= a['Site Owner'] ?? a.site_owner ?? null;

    const zapRefs  = extractUrls(a.reference || a.refs || '');

    const inst = Array.isArray(a.instances) && a.instances.length
      ? a.instances
      : [{ uri: null, method: null, param: null }];

    for (const it of inst){
      const url    = it.uri || it.url || null;
      const method = normMethod(it.method);
      const param  = normParam(it.param);

      const signature = { pluginid, title, url, method, param };

      rows.push({
        tool: 'zaproxy',
        title, pluginid, severity,
        description: desc,
        scanner_confidence: conf,
        cwe,
        site_owner: siteOwner,
        url, method, param,
        file_path: null,
        references: zapRefs.length ? zapRefs : undefined,
        signature
      });
    }
  }
  return rows;
}

// ---------- Checkov parser ----------
function parseCheckov(scan){
  const docs = Array.isArray(scan) ? scan : [scan];
  const rows = [];

  for (const doc of docs){
    const check_type = doc?.check_type || null;
    const failed = doc?.results?.failed_checks || [];
    if (!Array.isArray(failed)) continue;

    for (const v of failed){
      const check_id   = v.check_id || v.bc_check_id || null;
      const title      = (v.check_name || 'Checkov Finding').trim();
      const severity   = sevCheckov(v.severity);
      const result     = v.check_result?.result || '';
      const guideline  = v.guideline || '';
      const repo_owner = v['Repo Owner'] ?? v.repo_owner ?? null;
      const repo_link  = normRepoUrl(v['Repo Link']  ?? v.repo_link  ?? null);

      const file_path  = normPath(v.repo_file_path || v.file_abs_path || v.file_path || null);
      const resource   = v.resource || v.resource_address || null;

      let description = '';
      if (check_type) description += `Check Type: ${check_type}\n`;
      description += `Check Name: ${title}\n`;
      if (result)     description += `Result: ${result}\n`;
      if (check_id)   description += `Check Id: ${check_id}\n`;
      if (repo_owner) description += `Repo Owner: ${repo_owner}\n`;
      if (repo_link)  description += `Repo Link: ${repo_link}\n`;
      if (file_path)  description += `File: ${file_path}\n`;
      if (resource)   description += `Resource: ${resource}\n`;

      const signature = {
        pluginid: String(check_id || ''),
        check_type: check_type || null,
        repo: repo_link || null,
        file_path: file_path || null,
        resource: resource || null
      };

      rows.push({
        tool: 'checkov',
        title,
        pluginid: String(check_id || ''),
        severity,
        description,
        scanner_confidence: null,
        cwe: v.cwe || null,
        site_owner: repo_owner ?? null,
        url: repo_link || null,
        method: null,
        param: null,
        file_path,
        references: guideline ? [guideline] : undefined,
        signature
      });
    }
  }

  return rows;
}

// ---------- TruffleHog parser ----------
const TH_BASE_SEV = {
  'Github': 'High',
  'GitLab': 'High',
  'Slack': 'High',
  'AWS': 'High',
  'Google': 'High',
  'PrivateKey': 'Critical',
  'Stripe': 'High',
  'Twilio': 'High',
  'URI': 'Medium',
  'Generic' : 'Medium'
};
function sevTrufflehog(detectorName, verified){
  const base = TH_BASE_SEV[detectorName] || 'Medium';
  if (verified === true) {
    if (base === 'High') return 'Critical';
    if (base === 'Medium') return 'High';
  }
  return base;
}
function parseTrufflehog(scan){
  const findings = Array.isArray(scan) ? scan : [scan];
  const rows = [];

  for (const f of findings){
    if (!f || typeof f !== 'object') continue;
    const detector  = f.DetectorName || 'TruffleHog Secret';
    const verified  = !!f.Verified;
    const raw       = f.Raw || '';
    const redacted  = f.Redacted || '';
    const rawv2     = f.RawV2 || '';
    const file      = f.SourceMetadata?.Data?.Filesystem?.file || null;
    const line      = f.SourceMetadata?.Data?.Filesystem?.line || null;
    const repo_owner= f['Repo Owner'] ?? null;
    const repo_link = normRepoUrl(f['Repo Link'] ?? null);

    const severity  = sevTrufflehog(detector, verified);
    const title     = detector;

    const thRefs = unique([
      ...(extractUrls(f.ExtraData?.rotation_guide || '')),
      ...(extractUrls(f.ExtraData?.url || ''))
    ]);

    const extras = [];
    if (f.ExtraData && typeof f.ExtraData === 'object') {
      for (const [k,v] of Object.entries(f.ExtraData)) {
        if (v == null || v === '') continue;
        extras.push(`${k}: ${v}`);
      }
    }

    const descriptionLines = [
      `Detector: ${detector}`,
      `Verified: ${verified}`,
      repo_owner ? `Repo Owner: ${repo_owner}` : null,
      repo_link  ? `Repo Link: ${repo_link}`   : null,
      file       ? `File: ${file}`             : null,
      Number.isFinite(line) ? `Line: ${line}`  : null,
      redacted   ? `Redacted: ${redacted}`     : null,
      rawv2      ? `RawV2: ${rawv2}`           : null,
      ...extras
    ].filter(Boolean);

    const description = descriptionLines.join('\n');

    const signature = {
      detector,
      file: file || null,
      line: line ?? null,
      repo: repo_link || null,
      token_hint: redacted || (raw ? fnv1a64Hex(raw) : null)
    };

    rows.push({
      tool: 'trufflehog',
      title,
      pluginid: detector,
      severity,
      description,
      scanner_confidence: verified ? 7 : 2,
      cwe: null,
      site_owner: repo_owner,
      url: repo_link,
      method: null,
      param: null,
      file_path: file,
      references: thRefs.length ? thRefs : undefined,
      signature
    });
  }

  return rows;
}

// ---------- Kubescape parser (only failed) ----------
function parseKubescape(scan){
  const rows = [];
  if (!scan || typeof scan !== 'object') return rows;

  const summary = scan?.summaryDetails;
  const repoLink  = scan?.metadata?.targetMetadata?.gitRepoContextMetadata?.remoteURL || null;
  const ownerFromMeta = scan?.metadata?.targetMetadata?.gitRepoContextMetadata?.owner || null;

  function pushFinding(c){
    if (!c) return;
    const id   = c.controlID || c.id || null;
    const name = c.name || 'Kubescape Control';
    const severity = 'Medium';

    const rules = Array.isArray(c.rules) ? c.rules : [];
    const failedRules = rules.filter(r => (r?.status || '').toLowerCase() === 'failed');

    if (failedRules.length){
      for (const r of failedRules){
        const ruleName = r.name || 'rule';
        const paths = Array.isArray(r.paths) ? r.paths : [];
        const resourceIDs = paths.map(p => p.resourceID).filter(Boolean);
        const failedPath  = paths.map(p => p.failedPath).filter(Boolean);

        const description = [
          `Control: ${name} (${id})`,
          `Rule: ${ruleName}`,
          repoLink ? `Repo Link: ${normRepoUrl(repoLink)}` : null,
          resourceIDs.length ? `Resource IDs:\n- ${resourceIDs.join('\n- ')}` : null,
          failedPath.length  ? `Failed Paths:\n- ${failedPath.join('\n- ')}` : null
        ].filter(Boolean).join('\n');

        const signature = {
          control: id,
          rule: ruleName,
          repo: normRepoUrl(repoLink) || null
        };

        rows.push({
          tool: 'kubescape',
          title: name,
          pluginid: id,
          severity,
          description,
          scanner_confidence: null,
          cwe: null,
          site_owner: ownerFromMeta || null,
          url: normRepoUrl(repoLink) || null,
          method: null,
          param: null,
          file_path: null,
          signature
        });
      }
    } else {
      const status = (c.statusInfo?.status || c.status || '').toString().toLowerCase();
      if (status !== 'failed') return;

      const description = [
        `Control: ${name} (${id})`,
        repoLink ? `Repo Link: ${normRepoUrl(repoLink)}` : null
      ].filter(Boolean).join('\n');

      const signature = {
        control: id,
        rule: null,
        repo: normRepoUrl(repoLink) || null
      };

      rows.push({
        tool: 'kubescape',
        title: name,
        pluginid: id,
        severity: 'Medium',
        description,
        scanner_confidence: null,
        cwe: null,
        site_owner: ownerFromMeta || null,
        url: normRepoUrl(repoLink) || null,
        method: null,
        param: null,
        file_path: null,
        signature
      });
    }
  }

  if (summary && summary.controls && !Array.isArray(summary.controls)) {
    for (const [cid, c] of Object.entries(summary.controls)) {
      if (!c || typeof c !== 'object') continue;
      if (!c.controlID && !c.name && !c.status && !c.statusInfo) continue;
      pushFinding(c);
    }
  }

  if (Array.isArray(summary?.controls)) {
    for (const c of summary.controls) pushFinding(c);
  }

  return rows;
}

// ---------- Trivy remediation guidance builder ----------
function hasFixedVersion(fv){
  if (!fv) return false;
  const s = String(fv).trim();
  return !/^(none|null|n\/a|unknown|-|0)$/i.test(s);
}
function trivyGuidanceLines(pkg, installed, fixed, image, osType){
  const lines = [];
  const p = pkg || 'package';
  const inst = installed || 'unknown';

  if (hasFixedVersion(fixed)){
    lines.push(`Remediate: upgrade ${p} from ${inst} to ${fixed}.`);
    // OS-specific example commands (best-effort, short and safe)
    const t = (osType || '').toString().toLowerCase();
    if (t.includes('alpine')){
      lines.push(`Example (Alpine): rebuild image and run 'apk add --no-cache ${p}=${fixed}'.`);
    } else if (t.includes('debian') || t.includes('ubuntu')){
      lines.push(`Example (Debian/Ubuntu): rebuild image and run 'apt-get update && apt-get install --only-upgrade ${p}=${fixed}'.`);
    } else if (t.includes('redhat') || t.includes('rhel') || t.includes('centos') || t.includes('fedora') || t.includes('amazon') || t.includes('photon') || t.includes('oracle')){
      lines.push(`Example (RHEL-like): rebuild image and run 'yum update -y ${p}' or 'dnf upgrade -y ${p}'.`);
    } else {
      lines.push(`General: rebuild '${image || 'the image'}' with ${p} >= ${fixed}.`);
    }
  } else {
    // No fixed version known
    lines.push(`Mitigate: no fixed version available; consider removing or replacing ${p}, limiting exposure, or pinning to a safe base image while monitoring upstream advisories.`);
  }

  return lines;
}

// ---------- Trivy parser (container image vulnerabilities) ----------
// NOTE: references => GUIDANCE lines (first) + PrimaryURL (last). If no guidance could be built, references => [PrimaryURL] if present.
// Also emits image-level digest and per-vulnerability layer digest/diffId when available.
function parseTrivy(scan){
  const rows = [];
  if (!scan || typeof scan !== 'object') return rows;

  const artifactName = scan.ArtifactName || null;
  const imageOwner   = scan?.Results?.[0]?.Vulnerabilities?.[0]?.['Image Owner'] || null;
  const results = Array.isArray(scan.Results) ? scan.Results : [];
  const osFamily = scan?.Metadata?.OS?.Family || null;

  // Image-wide digest info
  const repoDigests = Array.isArray(scan?.Metadata?.RepoDigests) ? scan.Metadata.RepoDigests : [];
  const imageId     = scan?.Metadata?.ImageID || null;
  const imageDigest = repoDigests.length
    ? (repoDigests[0].split('@')[1] || repoDigests[0])
    : (imageId && imageId.startsWith('sha256:') ? imageId : null);

  for (const res of results){
    const vulns = Array.isArray(res.Vulnerabilities) ? res.Vulnerabilities : [];
    for (const v of vulns){
      const cve      = v.VulnerabilityID || v.ID || null;
      const pkgName  = v.PkgName || v.PkgID?.split('@')?.[0] || null;
      const InstalledVer   = v.InstalledVersion || null;
      const fixedVer = v.FixedVersion || null;
      const pkgId    = v.PkgID || null;
      const purl     = v.PkgIdentifier?.PURL || null;

      const severity = sevUpperToTitle(v.Severity);
      const title    = v.Title || cve || 'Trivy Vulnerability';
      const primaryUrl = v.PrimaryURL || v.PrimaryUrl || null;
      const desc = v.Description || '';


      // Description WITHOUT references (guidance + PrimaryURL are placed into references)
      const description = [
        `Severity Source: ${v.SeveritySource || 'unknown'}`,
        desc ? `Description: ${desc}` : null
      ].filter(Boolean).join('\n');

      // Build guidance and references
      const osType = res?.Type || osFamily || '';
      const guidance = trivyGuidanceLines(pkgName, InstalledVer, fixedVer, artifactName, osType);
      let references = [];
      if (guidance && guidance.length){
        references.push(...guidance);
        if (primaryUrl) references.push(primaryUrl);
      } else if (primaryUrl){
        references = [primaryUrl];
      }

      const signature = {
        pkg: pkgName || '',
        Installedversion: InstalledVer || '',
        fixedVersion: fixedVer || '',
        image: artifactName || ''
      };

      const imageObj = {
        name: artifactName || null,
        digest: imageDigest || null,
        imageId: imageId || null,
      };

      rows.push({
        tool: 'trivy',
        title,
        pluginid: cve || '',
        severity,
        description,
        scanner_confidence: null,
        cwe: (v.CweIDs && v.CweIDs[0]) || null,
        site_owner: imageOwner || null,
        url: null,
        method: null,
        param: null,
        file_path: null,
        package: {
          name: pkgName || null,
          InstalledVersion: InstalledVer || null,
          fixedVesion: fixedVer || null, // preserved for compatibility
          id: pkgId || null,
          purl: purl || null
        },
        image: imageObj,
        references: references.length ? references : undefined,
        signature
      });
    }
  }

  return rows;
}

// ---------- Prowler parser (AWS OCSF-like JSON) ----------
function parseProwler(scan){
  const docs = Array.isArray(scan) ? scan : [scan];
  const rows = [];

  for (const f of docs){
    if (!f || typeof f !== 'object') continue;

    const eventCode  = f.metadata?.event_code || null;
    const title      = (f.finding_info?.title || eventCode || 'Prowler Finding').trim();
    const severity   = sevUpperToTitle(f.severity);
    const status     = f.status || null;
    const statusCode = f.status_code || null;
    const statusDetail = f.status_detail || null;

    const risk       = f.risk_details || null;
    const remediationDesc = f.remediation?.desc || null;
    const remediationRefs = Array.isArray(f.remediation?.references) ? f.remediation.references : [];
    const compliance  = flattenCompliance(f.unmapped?.compliance);

    const res0       = Array.isArray(f.resources) && f.resources.length ? f.resources[0] : {};
    const resourceUid= res0.uid || null;
    const resourceName = res0.name || null;
    const resourceType = res0.type || null;
    const region     = res0.region || f.cloud?.region || null;
    const accountId  = f.cloud?.account?.uid || resourceName || null;
    const provider   = (f.cloud?.provider || 'aws').toLowerCase();

    const relatedUrl = f.unmapped?.related_url || '';
    const refList = unique(nonEmptyLines([relatedUrl, ...remediationRefs]));

    const descLines = [
      `Event Code: ${eventCode || 'unknown'}`,
      status ? `Status: ${status}${statusCode ? ` (${statusCode})` : ''}` : null,
      statusDetail ? `Status Detail: ${statusDetail}` : null,
      `Account: ${accountId || 'unknown'}`,
      region ? `Region: ${region}` : null,
      resourceUid ? `Resource UID: ${resourceUid}` : null,
      resourceType ? `Resource Type: ${resourceType}` : null,
      risk ? `Risk: ${risk}` : null,
      remediationDesc ? `Remediation: ${remediationDesc}` : null,
      compliance.length ? `Compliance:\n- ${compliance.join('\n- ')}` : null
    ].filter(Boolean);

    const description = descLines.join('\n');

    const signature = {
      pluginid: eventCode || '',
      provider,
      account: accountId || null,
      region: region || null,
      resource_uid: resourceUid || null
    };

    rows.push({
      tool: 'prowler',
      title,
      pluginid: eventCode || '',
      severity,
      description,
      scanner_confidence: null,
      cwe: null,
      site_owner: null,
      url: null,
      method: null,
      param: null,
      file_path: null,
      cloud: { provider, account_id: accountId || null, region: region || null },
      references: refList.length ? refList : undefined,
      signature
    });
  }

  return rows;
}

// ---------- MAIN ----------
const now = new Date().toISOString();
const inputItems = $input.all();
const out = [];

for (const item of inputItems){
  const j = item.json || {};

  // Source payload from "Extract from file"
  const scan        = j.scan ?? j.data ?? j.report ?? j.content ?? j.payload ?? {};
  const hintedTool  = j.tool ? String(j.tool).toLowerCase() : null;
  const mainIndex   = j.mainIndex   || 'security-findings';
  const eventsIndex = j.eventsIndex || 'security-findings-events';

  // s3 ONLY from this item (prevents cross-run leakage)
  const s3 = (j.s3 && j.s3.bucket && j.s3.key)
    ? { bucket: j.s3.bucket, key: j.s3.key }
    : (j.bucket && j.key)
      ? { bucket: j.bucket, key: j.key }
      : null;

  // Tool detection
  let tool = hintedTool;
  if (!tool){
    if (Array.isArray(scan) && scan.some(d => d?.results?.failed_checks)) tool = 'checkov';
    else if (scan?.results?.failed_checks) tool = 'checkov';
    else if (scan?.site || (Array.isArray(scan) && scan.some(d => d?.site))) tool = 'zaproxy';
    else if (Array.isArray(scan) && scan.some(d => d?.DetectorName || d?.SourceMetadata)) tool = 'trufflehog';
    else if (scan?.summaryDetails || scan?.metadata?.scanMetadata?.kubescapeVersion) tool = 'kubescape';
    else if (scan?.SchemaVersion && Array.isArray(scan?.Results)) tool = 'trivy';
    else if (Array.isArray(scan) && scan.some(d => d?.metadata?.product?.name === 'Prowler')) tool = 'prowler';
    else tool = 'unknown';
  }

  let findings = [];
  if (tool === 'zaproxy') findings = parseZap(scan);
  else if (tool === 'checkov') findings = parseCheckov(scan);
  else if (tool === 'trufflehog') findings = parseTrufflehog(scan);
  else if (tool === 'kubescape') findings = parseKubescape(scan);
  else if (tool === 'trivy') findings = parseTrivy(scan);
  else if (tool === 'prowler') findings = parseProwler(scan);
  else findings = [];

  // De-dupe within this item only
  const seen = new Set();

  for (const f of findings){
    const fingerprint = fingerprintOf(f.tool, f.signature);
    if (seen.has(fingerprint)) continue;
    seen.add(fingerprint);

    const mainDoc = {
      '@timestamp': now,
      tool: f.tool,
      title: f.title,
      severity: f.severity,
      description: f.description || '',
      scanner_confidence: f.scanner_confidence ?? null,
      site_owner: f.site_owner ?? null,
      cwe: f.cwe || null,
      pluginid: f.pluginid || null,
      url: f.url ?? null,
      method: f.method ?? null,
      param: f.param ?? null,
      ...(f.file_path ? { file_path: f.file_path } : {}),
      ...(f.package ? { package: f.package } : {}),
      ...(f.image ? { image: f.image } : {}),
      ...(f.cloud ? { cloud: f.cloud } : {}),
      ...(Array.isArray(f.references) && f.references.length ? { references: f.references } : {}),
      dedupe: { fingerprint, signature: f.signature }
    };

    const eventDoc = {
      '@timestamp': now,
      type: 'observation',
      fingerprint,
      tool: f.tool,
      title: f.title,
      severity: f.severity
    };

    if (s3){ mainDoc.s3 = s3; eventDoc.s3 = s3; }

    out.push({
      json: {
        now,
        fingerprint,
        mainIndex,
        eventsIndex,
        mainDoc,
        eventDoc
      }
    });
  }
}

return out;

// === Extra-safe Group & Collapse ===
// - Groups by fingerprint
// - Carries per-item indices, then picks a group-consistent index
// - Aggregates endpoints and file paths
// - Unions all S3 source objects (from both mainDoc/eventDoc)
// - Never reads indices from $json (avoids cross-item bleed)

// ---------- helpers ----------
const uniq = arr => Array.from(new Set((arr || []).filter(v => v != null && v !== '')));

function uniqSources(list) {
  const seen = new Set(), out = [];
  for (const s of list || []) {
    if (!s || !s.bucket || !s.key) continue;
    const id = `${s.bucket}|${s.key}`;
    if (seen.has(id)) continue;
    seen.add(id);
    out.push({ bucket: s.bucket, key: s.key });
  }
  return out;
}

// ---------- collect & group ----------
const groups = new Map();

for (const it of $input.all()) {
  const j = it.json || {};
  const fp = j.fingerprint;
  if (!fp) continue;

  const md = j.mainDoc || {};
  const ed = j.eventDoc || {};
  const mainIndex   = j.mainIndex   || 'security-findings';
  const eventsIndex = j.eventsIndex || 'security-findings-events';

  const arr = groups.get(fp) || [];
  arr.push({ md, ed, mainIndex, eventsIndex });
  groups.set(fp, arr);
}

// ---------- build outputs ----------
const out = [];

for (const [fp, arr] of groups) {
  if (!arr.length) continue;

  const first = arr[0].md || {};
  const occurrences_delta = arr.length;

  // endpoints (URLs) & file paths across occurrences
  const endpoints  = uniq(arr.map(x => x.md && x.md.url));
  const filePaths  = uniq(arr.map(x => x.md && x.md.file_path));

  // all s3 sources from mainDoc + eventDoc
  const s3Candidates = [
    ...arr.map(x => x.md && x.md.s3),
    ...arr.map(x => x.ed && x.ed.s3),
  ];
  const sources = uniqSources(s3Candidates);

  // choose indices safely from the group's own items
  const mainIdxSet   = new Set(arr.map(x => x.mainIndex).filter(Boolean));
  const eventsIdxSet = new Set(arr.map(x => x.eventsIndex).filter(Boolean));
  const groupMainIndex   = mainIdxSet.size   ? [...mainIdxSet][0]   : 'security-findings';
  const groupEventsIndex = eventsIdxSet.size ? [...eventsIdxSet][0] : 'security-findings-events';

  // optional warnings if mixed indices found within a group
  const warnings = [];
  if (mainIdxSet.size > 1)   warnings.push(`Mixed mainIndex for fingerprint ${fp}: ${[...mainIdxSet].join(', ')}`);
  if (eventsIdxSet.size > 1) warnings.push(`Mixed eventsIndex for fingerprint ${fp}: ${[...eventsIdxSet].join(', ')}`);

  // merge main doc: keep the first occurrence as the base,
  // but null-out per-occurrence HTTP fields and add aggregates.
  const mergedMain = {
    ...first,
    url: null,
    method: null,
    param: null,
  };
  if (endpoints.length) mergedMain.endpoints = endpoints;
  if (filePaths.length) mergedMain.file_paths = filePaths;

  // aggregate event: keep first's basics, attach count; keep first's s3 as canonical
  const aggEvent = {
    '@timestamp': first['@timestamp'] || new Date().toISOString(),
    type: 'observation',
    fingerprint: fp,
    tool: first.tool,
    title: first.title,
    severity: first.severity,
    count: occurrences_delta,
    s3: first.s3 || (sources.length ? sources[0] : undefined),
  };

  out.push({
    json: {
      fingerprint: fp,
      now: aggEvent['@timestamp'],
      mainIndex: groupMainIndex,
      eventsIndex: groupEventsIndex,
      occurrences_delta,
      mainDoc: mergedMain,
      eventDoc: aggEvent,
      sources,
      ...(warnings.length ? { warnings } : {})
    }
  });
}

return out;

function union(a, b){ const A=Array.isArray(a)?a:[], B=Array.isArray(b)?b:[]; const s=new Set(), out=[]; for (const x of [...A,...B]) if (x!=null && !s.has(x)) { s.add(x); out.push(x); } return out; }

const prev = $items('Collapse by Fingerprint');
const got  = $input.all();

const out = [];
for (let i = 0; i < got.length; i++) {
  const esItem   = got[i].json || {};
  const baseItem = (prev[i] && prev[i].json) ? prev[i].json : {};

  const existing = esItem.Document || esItem._source || null;
  const incoming = baseItem.mainDoc || {};
  const now      = baseItem.now;
  const delta    = baseItem.occurrences_delta || 1;

  const merged = existing ? {
    ...existing,
    ...incoming,
    occurrences: (existing.occurrences || 0) + delta,
    last_seen: now,
    endpoints: union(existing.endpoints, incoming.endpoints)
  } : {
    ...incoming,
    occurrences: delta,
    last_seen: now
  };

  out.push({
    json: {
      exists: !!existing,
      index: baseItem.mainIndex,
      id: baseItem.fingerprint,
      doc: merged,
      eventsIndex: baseItem.eventsIndex,
      eventDoc: baseItem.eventDoc,
      // 👇 carry forward all files to move
      sources: baseItem.sources,
      // optional: processed config from defaults if you added them earlier
      processedPrefix: baseItem.processedPrefix,
      processedBucket: baseItem.processedBucket
    }
  });
}
return out;

function cleanPrefix(p){
  let x = (p || 'processed/').toString().trim();
  x = x.replace(/^\/+/, '');       // no leading slash
  if (!x.endsWith('/')) x += '/';  // ensure trailing slash
  return x;
}

const prefix = cleanPrefix($json.processedPrefix);
const processedBucket = $json.processedBucket || null;

// prefer the union list from Collapse → Build; fallback to single doc.s3
const srcs = Array.isArray($json.sources) ? $json.sources
           : ($json.doc?.s3 ? [ $json.doc.s3 ] : []);

return srcs
  .filter(s => s && s.bucket && s.key)
  .map(s => {
    const sourcePath = `/${s.bucket}/${s.key}`;
    const destBucket = processedBucket || s.bucket;
    const destKey = `${prefix}${s.key}`;
    const destPath = `/${destBucket}/${destKey}`;
    return { json: {
      source: s,             // { bucket, key }
      sourcePath,            // "bucket/key"
      dest: { bucket: destBucket, key: destKey },
      destPath               // "bucket/prefix/key"
    }};
  });
